 <Dialog open={brief} onOpenChange={setBrief}><DialogContent className="brief-dialog"><DialogHeader><DialogTitle>Owner’s daily brief</DialogTitle><DialogDescription>{sample?'Illustrative sample summary':'From your saved company records'} · Dubai</DialogDescription></DialogHeader><div className="brief-metrics"><span><strong>{active.length}</strong>Active shipments</span><span><strong>{currency(ar)}</strong>Receivables</span><span><strong>{pending.length}</strong>Approvals</span></div><h3>Decisions waiting for you</h3>{pending.length?pending.map((a:any)=>{const r=data.find(r=>r.id===a.record_id);return <div className="approval-row" key={a.id}><div><strong>{r?.ref}</strong><p>{a.reason}</p></div><div><button disabled={sample||busy||role!=='owner'} className="btn small primary" onClick={()=>mutate('approval',null,{decision:'approved'},a.id)}>Approve</button><button disabled={sample||busy||role!=='owner'} className="btn small" onClick={()=>mutate('approval',null,{decision:'rejected'},a.id)}>Reject</button></div></div>;}):<p className="muted">No pending decisions.</p>}<h3>At-risk work</h3>{attention.map(a=><button className="brief-risk" key={a.r.id} onClick={()=>{setBrief(false);setSelected(a.r.id);}}><strong>{a.title}</strong><span>{a.r.ref} · {a.text}</span><ChevronRight size={16}/></button>)}<button className="btn" onClick={()=>{navigator.clipboard?.writeText(`Elvora daily brief\nActive shipments: ${active.length}\nReceivables: ${currency(ar)}\nExpected job GP: ${currency(gp)}\nPending approvals: ${pending.length}`).then(()=>toast.success('Daily brief copied.')).catch(()=>toast.error('Copy unavailable.'));}}>Copy brief</button></DialogContent></Dialog>
